import type { Db } from '../client';

/**
 * Every repo is a plain factory function `createXRepo(db)` — no classes,
 * matching the functional style the rest of the codebase uses. Repos never
 * compute rules (spec 4.2): they accept fully-formed rows (ids are ULIDs
 * generated by the caller, timestamps are passed in, not read from the
 * clock here) and return plain objects typed by Drizzle's inferred types.
 */
export type { Db };
